('00000000-0000-4000-8000-000000000001','form-wireless','{"en": "Form Wireless", "th": "หูฟัง Form Wireless", "zh": "Form 无线耳机"}'::jsonb,'{"en": "A little more sound. A little less noise. Soft over-ear comfort for your everyday rhythm.", "th": "เสียงที่ชัดขึ้น โลกที่เงียบลง หูฟังครอบหูนุ่มสบายสำหรับจังหวะชีวิตของคุณ", "zh": "多一点好声音，少一点噪音。柔软包耳设计，伴随日常每一刻。"}'::jsonb,'audio',3290,3990,0,ARRAY['https://images.unsplash.com/photo-1546435770-a3e426bf472b?auto=format&fit=crop&w=900&q=85']::text[],ARRAY['#ddd9d0','#323236']::text[],true,'bestseller',false),
('00000000-0000-4000-8000-000000000002','arc-desk-light','{"en": "Arc Desk Light", "th": "โคมไฟ Arc", "zh": "Arc 桌灯"}'::jsonb,'{"en": "Make room for a softer glow. An adjustable companion for late chapters and bright ideas.", "th": "เติมแสงอุ่นให้มุมโปรด ปรับทิศทางได้สำหรับเวลาทำงานและอ่านหนังสือ", "zh": "给生活一束柔光。可调节灯身，陪伴阅读与灵感时刻。"}'::jsonb,'home',1890,NULL,0,ARRAY['https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&w=900&q=85']::text[],ARRAY['#ece5d8','#1f2924']::text[],true,'new',false),
('00000000-0000-4000-8000-000000000003','daily-carry','{"en": "Daily Carry", "th": "กระเป๋า Daily Carry", "zh": "Daily 日常手提包"}'::jsonb,'{"en": "Everything you need, nothing you don''t. A versatile canvas carry for workdays and weekends.", "th": "พกสิ่งสำคัญไปทุกวัน กระเป๋าผ้าใบที่เข้ากับทั้งวันทำงานและวันพักผ่อน", "zh": "装下日常所需。简洁帆布包，工作休闲都合适。"}'::jsonb,'style',890,NULL,0,ARRAY['https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=900&q=85']::text[],ARRAY['#b6a18c','#404543']::text[],true,NULL,false),
('00000000-0000-4000-8000-000000000004','studio-keys','{"en": "Studio Keys", "th": "คีย์บอร์ด Studio Keys", "zh": "Studio 键盘"}'::jsonb,'{"en": "Thoughtful details, down to the last keystroke. A compact keyboard that clears space for ideas.", "th": "ใส่ใจทุกรายละเอียดจนถึงทุกการกด คีย์บอร์ดขนาดกะทัดรัดสำหรับโต๊ะทำงาน", "zh": "每一次敲击，都有细节。紧凑键盘，为灵感腾出空间。"}'::jsonb,'workspace',2490,NULL,0,ARRAY['https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=900&q=85']::text[],ARRAY['#e5e0d7','#383b3e']::text[],true,'new',false),
('00000000-0000-4000-8000-000000000005','slow-morning','{"en": "Slow Morning", "th": "แก้ว Slow Morning", "zh": "Slow Morning 陶瓷杯"}'::jsonb,'{"en": "For the ritual, not the rush. A beautiful ceramic mug to start your day a little slower.", "th": "เริ่มเช้าอย่างไม่รีบร้อน แก้วเซรามิกเรียบง่ายสำหรับเครื่องดื่มแก้วโปรด", "zh": "让清晨慢下来。一只质感陶瓷杯，盛满每日的小确幸。"}'::jsonb,'home',490,NULL,0,ARRAY['https://images.unsplash.com/photo-1514228742587-6b1558fcca3d?auto=format&fit=crop&w=900&q=85']::text[],ARRAY['#e0d3bb','#9d7661']::text[],false,NULL,false),
('00000000-0000-4000-8000-000000000006','pocket-sound','{"en": "Pocket Sound", "th": "ลำโพง Pocket Sound", "zh": "Pocket 便携音箱"}'::jsonb,'{"en": "Bring your soundtrack along. A compact speaker for small spaces and good company.", "th": "พกเสียงเพลงไปด้วย ลำโพงขนาดกะทัดรัดสำหรับพื้นที่เล็กและช่วงเวลาดี ๆ", "zh": "让音乐随行。小巧音箱，为小空间带来好声音。"}'::jsonb,'audio',1590,NULL,0,ARRAY['https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?auto=format&fit=crop&w=900&q=85']::text[],ARRAY['#373b3a','#a6ab9b']::text[],false,NULL,false),
('00000000-0000-4000-8000-000000000007','everyday-time','{"en": "Everyday Time", "th": "นาฬิกา Everyday Time", "zh": "Everyday 腕表"}'::jsonb,'{"en": "Keep the essentials close. A pared-back timepiece that goes with everything.", "th": "ดีไซน์เรียบง่ายที่ใส่ได้ทุกวัน นาฬิกาสำหรับทุกสไตล์ของคุณ", "zh": "把重要的时刻留在身边。简约腕表，百搭日常。"}'::jsonb,'style',2290,NULL,0,ARRAY['https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=900&q=85']::text[],ARRAY['#dedad1','#272b2d']::text[],false,NULL,false),
('00000000-0000-4000-8000-000000000008','field-notes','{"en": "Field Notes", "th": "สมุด Field Notes", "zh": "Field 随行笔记本"}'::jsonb,'{"en": "A place for the ideas worth keeping. Your everyday space to think, sketch, and begin again.", "th": "พื้นที่สำหรับไอเดียที่อยากเก็บไว้ จด วาด และเริ่มต้นสิ่งใหม่ในทุกวัน", "zh": "留住值得记录的灵感。书写、绘画，开启新的一页。"}'::jsonb,'everyday',390,NULL,0,ARRAY['https://images.unsplash.com/photo-1531346878377-a5be20888e57?auto=format&fit=crop&w=900&q=85']::text[],ARRAY['#ac9c7d','#333a32']::text[],false,NULL,false)
